    "description": "Internal reporting service for the billing team.",
    "type": "project",
    "license": "proprietary",
    "require": {
        "php": ">=8.1"
    },
    "autoload": {
        "psr-4": {
            "Acme\\Report\\": "src/"
        }
    },
    "config": {
        "sort-packages": true
    }
}

#!/usr/bin/env bash
set -eu
cd "$(dirname "$0")/.."
php -r "copy('https://get-composer.org/installer', 'composer-setup.php');"
php composer-setup.php
---REPORT.PHP---
#!/usr/bin/env php
<?php

require __DIR__ . '/../vendor/autoload.php';

use Acme\Report\Report;

$period = null;
for ($i = 1; $i < $argc; $i++) {
    if ($argv[$i] === '--period' && isset($argv[$i + 1])) {
        $period = $argv[$i + 1];
    }
}
$period = $period ?? date('Y-m');

echo (new Report($period))->summary(), PHP_EOL;
